package com.xcosmos.minivoice;
import java.io.*;import java.nio.*;import java.nio.charset.*;import java.nio.file.*;import java.util.*;
/** Non-fragmented M4A/iTunes metadata. Original media/chunk offsets stay unchanged. */
final class PortableM4aTags {
 static final Charset CODE=StandardCharsets.ISO_8859_1;
 static byte[] atom(String type,byte[] data)throws IOException{if(data.length>PortableTagCodec.LIMIT)throw new IOException("M4A 标签过大");ByteArrayOutputStream out=new ByteArrayOutputStream();out.write(ByteBuffer.allocate(4).putInt(data.length+8).array());out.write(type.getBytes(CODE));out.write(data);return out.toByteArray();}
 static List<byte[]> children(byte[] data,int prefix)throws IOException{List<byte[]> rows=new ArrayList<>();for(int pos=prefix;pos<data.length;){if(pos+8>data.length)throw new IOException("M4A 子标签损坏");int count=ByteBuffer.wrap(data,pos,4).getInt();if(count<8||count>data.length-pos)throw new IOException("M4A 子标签长度无效");rows.add(Arrays.copyOfRange(data,pos,pos+count));pos+=count;if(rows.size()>10000)throw new IOException("M4A 子标签过多");}return rows;}
 static String type(byte[] atom){return new String(atom,4,4,CODE);}
 static byte[] body(byte[] atom){return Arrays.copyOfRange(atom,8,atom.length);}
 static byte[] replace(byte[] data,int prefix,String child,byte[] replacement)throws IOException{ByteArrayOutputStream out=new ByteArrayOutputStream();out.write(data,0,prefix);boolean found=false;for(byte[] row:children(data,prefix)){if(type(row).equals(child)){if(found)throw new IOException("M4A 含重复元数据块");found=true;out.write(replacement);}else out.write(row);}if(!found)out.write(replacement);return out.toByteArray();}
 static byte[] find(byte[] data,int prefix,String wanted)throws IOException{byte[] result=null;for(byte[] row:children(data,prefix))if(type(row).equals(wanted)){if(result!=null)throw new IOException("M4A 含重复元数据块");result=body(row);}return result;}
 static byte[] edit(byte[] moov,String title,String artist,String album,String lyrics)throws IOException{
  if(find(moov,0,"mvex")!=null||find(moov,0,"cmov")!=null)throw new IOException("暂不支持分片或压缩 M4A");
  byte[] udta=find(moov,0,"udta");if(udta==null)udta=new byte[0];byte[] meta=find(udta,0,"meta");if(meta==null){ByteArrayOutputStream initial=new ByteArrayOutputStream();initial.write(new byte[4]);ByteArrayOutputStream handler=new ByteArrayOutputStream();handler.write(new byte[8]);handler.write("mdir".getBytes(CODE));handler.write(new byte[13]);initial.write(atom("hdlr",handler.toByteArray()));meta=initial.toByteArray();}if(meta.length<4||ByteBuffer.wrap(meta,0,4).getInt()!=0)throw new IOException("不支持此 M4A 元数据版本");
  byte[] list=find(meta,4,"ilst");if(list==null)list=new byte[0];String[] keys={"©nam","©ART","©alb","©lyr"},values={title,artist,album,lyrics};
  for(int i=0;i<keys.length;i++){ByteArrayOutputStream value=new ByteArrayOutputStream();value.write(new byte[]{0,0,0,1,0,0,0,0});value.write(values[i].getBytes(StandardCharsets.UTF_8));list=replace(list,0,keys[i],atom(keys[i],atom("data",value.toByteArray())));}
  return replace(moov,0,"udta",atom("udta",replace(udta,0,"meta",atom("meta",replace(meta,4,"ilst",atom("ilst",list))))));
 }
 static void rewrite(File source,File target,String title,String artist,String album,String lyrics)throws IOException{
  long moovOffset=-1,moovSize=0;byte[] moov=null;boolean brand=false;
  try(RandomAccessFile file=new RandomAccessFile(source,"r")){for(long offset=0;offset<file.length();){if(file.length()-offset<8)throw new IOException("M4A 原子不完整");file.seek(offset);long count=Integer.toUnsignedLong(file.readInt());byte[] type=new byte[4];file.readFully(type);String name=new String(type,CODE);int header=8;if(count==1){count=file.readLong();header=16;}if(count<header||count>file.length()-offset)throw new IOException("M4A 长度无效");if(offset==0&&!name.equals("ftyp"))throw new IOException("文件并非 M4A");if(name.equals("ftyp"))brand=true;if(name.equals("moof"))throw new IOException("暂不支持分片 M4A");if(name.equals("moov")){if(moov!=null||count-header>PortableTagCodec.LIMIT)throw new IOException("M4A 电影信息异常");moovOffset=offset;moovSize=count;moov=new byte[(int)count-header];file.readFully(moov);}offset+=count;}}
  if(!brand||moov==null)throw new IOException("M4A 缺少电影信息");byte[] edited=atom("moov",edit(moov,title,artist,album,lyrics));Files.copy(source.toPath(),target.toPath(),StandardCopyOption.REPLACE_EXISTING);
  try(RandomAccessFile file=new RandomAccessFile(target,"rw")){if(moovOffset+moovSize==file.length())file.setLength(moovOffset);else{file.seek(moovOffset+4);file.write("free".getBytes(CODE));}file.seek(file.length());file.write(edited);}
 }
 static AudioTags read(InputStream input)throws IOException{DataInputStream in=new DataInputStream(input);for(int i=0;i<10000;i++){long count;try{count=Integer.toUnsignedLong(in.readInt());}catch(EOFException end){return new AudioTags();}byte[] name=new byte[4];in.readFully(name);int header=8;if(count==1){count=in.readLong();header=16;}if(count<header)throw new IOException("M4A 长度无效");long remaining=count-header;if(new String(name,CODE).equals("moov")){byte[] moov=PortableTagCodec.read(in,(int)Math.min(Integer.MAX_VALUE,remaining));byte[] udta=find(moov,0,"udta"),meta=udta==null?null:find(udta,0,"meta"),list=meta==null?null:find(meta,4,"ilst");AudioTags tags=new AudioTags();tags.lyricsChecked=true;if(list!=null)for(byte[] row:children(list,0)){byte[] data=find(body(row),0,"data");if(data==null||data.length<8||ByteBuffer.wrap(data,0,4).getInt()!=1)continue;String text=new String(data,8,data.length-8,StandardCharsets.UTF_8);switch(type(row)){case "©nam":tags.title=text;break;case "©ART":tags.artist=text;break;case "©alb":tags.album=text;break;case "©lyr":tags.lyrics=text;break;}}return tags;}while(remaining>0){long skipped=in.skip(remaining);if(skipped==0){if(in.read()<0)throw new EOFException();skipped=1;}remaining-=skipped;}}throw new IOException("M4A 原子过多");}
}
